#include <fstream>
#include <string>
#include <map>

using namespace std;

int main()
{
    string palabra; // Palabra a buscar
    int contador = 0;

    // Obtenga la palabra a buscar de la entrada estándar
    cout << "Introduzca la palabra a buscar: ";
    cin >> palabra;

    // Abre el archivo de texto para leer
    string archivo = "archivo.txt"; // Reemplaza este valor con el nombre del archivo de texto
