        cerr << "No se pudo abrir el archivo: " << archivo << endl;
        return 1;
    }

    // Crea un mapa para almacenar las ocurrencias de la palabra
    map<string, int> ocurrencias;

    // Lee el archivo línea por línea y cuenta las ocurrencias de la palabra
    string linea;
    while (getline(file, linea)) {
        // Convierte la línea en una cadena de palabras
        istringstream palabras(linea);
        string palabraActual;
        while (palabras >> palabraActual) {
            if (palabraActual == palabra) {
                ocurrencias[palabra]++;
                contador++;
            }
        }
