    cout << "Ocurrencias: " << contador << endl;
    for (const auto& [palabra, ocurrencia] : ocurrencias) {
        if (palabra == palabra) {
            cout << "  " << palabra << ": " << ocurrencia << endl;
        }
    }

    // Cierra el archivo
